package fraymus.workspace;

import org.json.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.BooleanSupplier;

/** Original native load sweeps and repeated tested endpoints; never a continuous strength guarantee. */
final class Load056 {
    static final String VERSION="measured-load-envelope-056-v1";
    private Load056(){}
    static JSONObject protocol(){try(var in=Load056.class.getResourceAsStream("/construction056-protocol.json")){return new JSONObject(new String(in.readAllBytes(),StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException(e);}}
    static int required(JSONObject input){if(!input.has("requiredLoadN"))return protocol().getInt("defaultRequiredN");double value=SpatialScene.number(input,"requiredLoadN",8,64);for(Object raw:protocol().getJSONArray("levelsN"))if(((Number)raw).doubleValue()==value)return(int)value;throw new IllegalArgumentException("Choose a tested load:8,16,24,32,48 or64N");}
    static String code(){var d=new JSONObject().put("native",WorldNativeCheckpoint.identity()).put("loadKernel",Load055.code()).put("protocol",protocol());for(Class<?> c:new Class<?>[]{Load056.class,Design056.class})try(var in=c.getResourceAsStream(c.getSimpleName()+".class")){d.put(c.getSimpleName(),MapDefinition.sha(in.readAllBytes()));}catch(Exception e){throw new IllegalStateException(e);}return WorldFrames.hash(d);}
    static JSONObject spec(JSONObject run,int force){double length=WorldPlan.sourceObject(run.getJSONObject("definition"),"beam").getJSONArray("size").getDouble(0);return new JSONObject().put("id","eccentric-"+force).put("forceN",new JSONArray(new int[]{0,-force,0})).put("localPointM",new JSONArray(new double[]{length*.5*protocol().getDouble("pointHalfLengthFraction"),0,0}));}
    private static Path file(Path root,JSONObject run){UUID.fromString(run.getString("id"));return root.resolve(run.getString("id")+".json");}
    private static JSONObject load(Path path)throws Exception{var e=AgentFiles042.read(path,protocol().getInt("maxBytes"));var d=e.getJSONObject("data");if(!e.getString("format").equals("java-agent-042-v1")||!WorldFrames.hash(d).equals(e.getString("sha256")))throw new IllegalStateException("Load envelope checksum changed");return d;}
    private static void save(Path path,JSONObject d)throws Exception{if(d.toString().getBytes(StandardCharsets.UTF_8).length>protocol().getInt("maxBytes")-1000)throw new IllegalStateException("Load envelope exceeds64MB; prior checkpoint retained");AgentFiles042.saveChecked(path,d);}
    private static void bound(JSONObject d,JSONObject run,int required){if(!d.getString("version").equals(VERSION)||!d.getString("codeSha256").equals(code())||!d.getString("sourceRunSha256").equals(WorldFrames.hash(run))||d.getInt("requiredLoadN")!=required)throw new IllegalStateException("Load envelope source, code or requirement changed");if(d.getJSONArray("attempts").length()>protocol().getInt("maxAttempts"))throw new IllegalStateException("Load attempt budget changed");var ids=new HashSet<String>();for(Object raw:d.getJSONArray("attempts")){var a=(JSONObject)raw;UUID.fromString(a.getString("id"));if(!ids.add(a.getString("id"))||!Set.of("running","interrupted","failed","completed").contains(a.getString("status"))||a.getInt("repeat")<0||a.getInt("repeat")>2||!spec(run,a.getInt("forceMagnitudeN")).similar(a.getJSONObject("spec"))||a.getJSONArray("rows").length()>Load055.protocol().getInt("ticks"))throw new IllegalStateException("Invalid load attempt identity/point/bounds");boolean level=false;for(Object n:protocol().getJSONArray("levelsN"))if(((Number)n).intValue()==a.getInt("forceMagnitudeN"))level=true;if(!level)throw new IllegalStateException("Undeclared load level");}}
    static JSONObject evaluate(Path root,JSONObject run,int required,BooleanSupplier cancelled)throws Exception{
        if(!WorldVerify.verify(run).getBoolean("passed")||!Construction051.verifyStructure(run).getBoolean("passed"))throw new IllegalStateException("Envelope requires original released assembly proof");required(new JSONObject().put("requiredLoadN",required));Path path=file(root,run);var d=Files.exists(path)?load(path):new JSONObject().put("version",VERSION).put("codeSha256",code()).put("sourceRunSha256",WorldFrames.hash(run)).put("requiredLoadN",required).put("attempts",new JSONArray());bound(d,run,required);
        for(Object raw:d.getJSONArray("attempts")){var a=(JSONObject)raw;if(a.getString("status").equals("running"))a.put("status","interrupted").put("reason","Prior owner ended; partial original retained");}
        for(Object raw:protocol().getJSONArray("levelsN"))attempt(root,path,d,run,((Number)raw).intValue(),0,cancelled);
        var bracket=bracket(d,run);var repeatFor=new LinkedHashSet<Integer>();if(bracket.get("stablePrefixN")!=JSONObject.NULL)repeatFor.add(bracket.getInt("stablePrefixN"));if(bracket.get("firstUnstableN")!=JSONObject.NULL)repeatFor.add(bracket.getInt("firstUnstableN"));repeatFor.add(required);
        for(int force:repeatFor)for(int repeat=1;repeat<=protocol().getInt("endpointRepeats");repeat++)attempt(root,path,d,run,force,repeat,cancelled);
        return read(root,run,required);
    }
    private static JSONObject completed(JSONObject d,JSONObject run,int force,int repeat){JSONObject found=null;for(Object raw:d.getJSONArray("attempts")){var a=(JSONObject)raw;if(a.getInt("forceMagnitudeN")==force&&a.getInt("repeat")==repeat&&a.getString("status").equals("completed")){if(found!=null)throw new IllegalStateException("Duplicate completed load case");var metrics=Load055.verifyAttempt(new JSONObject(a.toString()),run,spec(run,force));if(!metrics.similar(a.getJSONObject("metrics")))throw new IllegalStateException("Retained envelope metrics changed");found=a;}}return found;}
    private static void attempt(Path root,Path path,JSONObject d,JSONObject run,int force,int repeat,BooleanSupplier cancelled)throws Exception{
        if(completed(d,run,force,repeat)!=null)return;if(cancelled.getAsBoolean()||Thread.interrupted())throw new InterruptedException("Load envelope stopped; originals retained");if(d.getJSONArray("attempts").length()>=protocol().getInt("maxAttempts"))throw new IllegalStateException("Load attempt budget exhausted; originals retained");
        var s=spec(run,force);var a=new JSONObject().put("id",UUID.randomUUID().toString()).put("forceMagnitudeN",force).put("repeat",repeat).put("spec",s).put("startedAt",Instant.now()).put("status","running").put("initial",WorldFrames.copy(run.getJSONObject("final"))).put("rows",new JSONArray()).put("samples",new JSONArray());d.getJSONArray("attempts").put(a);save(path,d);long start=System.nanoTime();
        try{Load055.simulate(root.resolve("native"),run,s,a,()->{if(cancelled.getAsBoolean()||Thread.interrupted())throw new InterruptedException("Load envelope stopped; original partial attempt retained");save(path,d);return null;});a.put("metrics",Load055.verifyAttempt(new JSONObject(a.toString()),run,s)).put("status","completed");}
        catch(InterruptedException e){a.put("status","interrupted").put("reason",e.getMessage());throw e;}
        catch(Exception e){boolean stopped=Thread.interrupted();a.put("status",stopped?"interrupted":"failed").put("reason",e.toString());if(stopped)throw new InterruptedException("Load checkpoint interrupted");throw e;}
        finally{a.put("wallMillis",(System.nanoTime()-start)/1_000_000.0);save(path,d);}
    }
    private static JSONObject bracket(JSONObject d,JSONObject run){Integer stable=null,unstable=null;boolean nonMonotonic=false;var rows=new JSONArray();for(Object raw:protocol().getJSONArray("levelsN")){int force=((Number)raw).intValue();var a=completed(d,run,force,0);if(a==null)throw new IllegalStateException("Unfinished envelope level:"+force);boolean pass=a.getJSONObject("metrics").getBoolean("stable");if(!pass&&unstable==null)unstable=force;if(pass&&unstable==null)stable=force;if(pass&&unstable!=null)nonMonotonic=true;rows.put(new JSONObject().put("forceN",force).put("stable",pass).put("metrics",a.getJSONObject("metrics")).put("attemptId",a.getString("id")));}return new JSONObject().put("stablePrefixN",stable==null?JSONObject.NULL:stable).put("firstUnstableN",unstable==null?JSONObject.NULL:unstable).put("nonMonotonic",nonMonotonic).put("levels",rows);}
    static JSONObject read(Path root,JSONObject run,int required)throws Exception{var d=load(file(root,run));bound(d,run,required);var result=bracket(d,run);var repeats=new LinkedHashSet<Integer>();if(!result.isNull("stablePrefixN"))repeats.add(result.getInt("stablePrefixN"));if(!result.isNull("firstUnstableN"))repeats.add(result.getInt("firstUnstableN"));repeats.add(required);boolean repeatable=true,requiredStable=true;var rows=new JSONArray();for(int force:repeats){var first=completed(d,run,force,0);for(int repeat=1;repeat<=protocol().getInt("endpointRepeats");repeat++){var a=completed(d,run,force,repeat);if(a==null)throw new IllegalStateException("Unfinished repeated load case");boolean stable=a.getJSONObject("metrics").getBoolean("stable");repeatable&=stable==first.getJSONObject("metrics").getBoolean("stable");if(force==required)requiredStable&=stable;rows.put(new JSONObject().put("forceN",force).put("repeat",repeat).put("stable",stable).put("attemptId",a.getString("id")).put("metrics",a.getJSONObject("metrics")));}}
        long ticks=0;double wall=0,effort=0;for(Object raw:d.getJSONArray("attempts")){var a=(JSONObject)raw;ticks+=a.getJSONArray("rows").length();wall+=a.optDouble("wallMillis",0);for(Object item:a.getJSONArray("rows"))effort+=WorldVerify.norm(((JSONArray)item).getJSONArray(1))*BulletRamp.DT;}
        requiredStable&=completed(d,run,required,0).getJSONObject("metrics").getBoolean("stable");boolean qualifies=requiredStable&&repeatable&&!result.getBoolean("nonMonotonic")&&!result.isNull("stablePrefixN")&&result.getInt("stablePrefixN")>=required;
        return result.put("version",VERSION).put("scope",protocol().getString("scope")).put("complete",true).put("qualifies",qualifies).put("repeatable",repeatable).put("requiredLoadN",required).put("repeats",rows).put("applicationPointLocalM",spec(run,required).getJSONArray("localPointM")).put("sourceRunSha256",WorldFrames.hash(run)).put("codeSha256",code()).put("originalSha256",WorldFrames.hash(d)).put("attempts",d.getJSONArray("attempts").length()).put("totalTicks",ticks).put("forceEffortNs",effort).put("wallMillis",wall);
    }
    static JSONObject original(Path root,JSONObject run,int required)throws Exception{var d=load(file(root,run));bound(d,run,required);for(Object raw:d.getJSONArray("attempts")){var a=(JSONObject)raw;if(a.getString("status").equals("completed")&&!Load055.verifyAttempt(a,run,a.getJSONObject("spec")).similar(a.getJSONObject("metrics")))throw new IllegalStateException("Original envelope changed");}return WorldReport.packed(d).put("format","fraynix.load-envelope-gzip-v1");}
    static String label(JSONObject r){return "Requested "+r.getInt("requiredLoadN")+" N: "+(r.getBoolean("qualifies")?"verified":"not verified")+"; tested stable prefix "+(r.isNull("stablePrefixN")?"none":r.getInt("stablePrefixN")+" N")+"; first tested failure "+(r.isNull("firstUnstableN")?"not found through64 N":r.getInt("firstUnstableN")+" N")+"; repeats "+(r.getBoolean("repeatable")?"agree":"DISAGREE");}
}
